using UnityEngine;using UnityEditor;using System.Linq;
public static class InspectRoadBlock {public static string Main(){var v=SceneView.lastActiveSceneView;return "play="+Application.isPlaying+" view="+(v==null?"none":v.pivot.ToString()+" camera="+v.camera.transform.position)+"\n"+string.Join("\n",Object.FindObjectsByType<MotorollerController>(FindObjectsSortMode.None).Select(m=>m.name+" pos="+m.transform.position+" forward="+m.transform.forward+" speed="+m.Speed))+"\nterrains="+string.Join(";",Terrain.activeTerrains.Select(t=>t.name+" "+t.transform.position+" "+t.terrainData.size));}}
